#include "CloseToHSL/Core/Virtualization/Compatibility/Frontend/Projection/YAKSys_Hybrid_CPU.Core.VmxCompatProjectionService.h"
#include <cassert>
using namespace YAKSys_Hybrid_CPU::Core;
int main(){ VmxCompatProjectionService service; auto r=std::make_shared<VmxCompatProjectionRequest>(); r->SourceKind=CompatAliasSourceKind::Opcode; r->SourceName=L"VMXON"; assert(service.ValidateProjection(r)->Decision==VmxCompatProjectionDecision::DescriptorValidationDenied); r->DescriptorValidated=true; assert(service.ValidateProjection(r)->Decision==VmxCompatProjectionDecision::EvidenceValidationDenied); r->EvidenceValidated=true; r->AttemptsAuthoritativeMutation=true; assert(service.ValidateProjection(r)->Decision==VmxCompatProjectionDecision::AuthoritativeMutationDenied); r->AttemptsAuthoritativeMutation=false; auto allowed=service.ValidateProjection(r); assert(allowed->getIsAllowed() && allowed->Alias->SourceName==L"VMXON"); r->SourceName=L"missing"; auto denied=service.ValidateProjection(r); assert(denied->Decision==VmxCompatProjectionDecision::UnknownAlias && denied->Alias && denied->Alias->SourceName.empty()); }
